mapper.select:
SELECT s.id, s.subject_code, s.subject_name, s.subject_desc, s.grade_id, g.grade_name, s.school_id, s.enabled, s.create_time, u.actual_name AS createUser FROM t_as_subject s LEFT JOIN t_educl_grade g ON s.grade_id = g.id LEFT JOIN t_base_user u ON s.create_user = u.id
s.is_valid = 1
AND s.school_id = #{query.schoolId}
AND s.grade_id = #{query.gradeId}
AND s.subject_name LIKE concat('%', #{query.subjectName}, '%')
AND s.subject_code = #{query.subjectCode}
AND s.enabled = #{query.enabled}
ORDER BY s.create_time desc
